const L = vars.length, H = vars.height, T = vars.thickness, nw = Math.round(vars.windows), bays = nw + (vars.door ? 1 : 0);
const z = addpoint(0, [0, 0, 0]);
for (const g of ['cut', 'win_at', 'door_at']) setpointgroup(0, g, z, 0);
if (!bays) return;
const bw = L / bays, dbay = vars.door ? Math.floor(bays / 2) : -1;
const ww = Math.min(vars.window_width, bw - 0.2), sill = Math.min(vars.sill_height, H - 0.45), wh = Math.min(vars.window_height, H - sill - 0.15);
const dw = Math.min(1, bw - 0.2), dh = Math.min(2.1, H - 0.15);
for (let i = 0; i < bays; i++) {
  const x = bw * (i + 0.5), door = i === dbay;
  if ((door ? dw : ww) <= 0.05 || (door ? dh : wh) <= 0.05) continue;
  const c = addpoint(0, door ? [x, (dh - 0.05) / 2, 0] : [x, sill + wh / 2, 0]);
  setpointattrib(0, 'scale', c, door ? [dw, dh + 0.05, T + 0.2] : [ww, wh, T + 0.2]);
  setpointgroup(0, 'cut', c, 1);
  const a = addpoint(0, [x, door ? 0 : sill, 0]);
  setpointgroup(0, door ? 'door_at' : 'win_at', a, 1);
}
